// Adapted from tenantadmin server/src/services/authService.js:422-484 @ e9a4b45
// (Prisma replaced by an in-memory store with the same semantics: findFirst is an
// async read, updateMany is an atomic conditional write returning { count }).
import { createHash, randomBytes } from 'node:crypto';

export class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

export const hashToken = (token) => createHash('sha256').update(token).digest('hex');

export function createStore() {
  const tick = () => new Promise((r) => setTimeout(r, 1));
  const store = {
    tokens: [],
    sessions: [],
    magicLinkToken: {
      async findFirst({ where }) {
        await tick();
        const t = store.tokens.find((x) => x.tokenHash === where.tokenHash && x.consumedAt === null && x.expiresAt > where.now);
        return t ? { ...t } : null;
      },
      async updateMany({ where, data }) {
        await tick();
        const rows = store.tokens.filter((x) => x.id === where.id && (where.consumedAt === undefined || x.consumedAt === where.consumedAt));
        for (const r of rows) Object.assign(r, data);
        return { count: rows.length };
      },
      async update({ where, data }) {
        await tick();
        const r = store.tokens.find((x) => x.id === where.id);
        Object.assign(r, data);
        return { ...r };
      },
    },
    async $transaction(fn) {
      return fn(store);
    },
  };
  return store;
}

export function issueToken(store, userId) {
  const token = randomBytes(24).toString('hex');
  store.tokens.push({ id: `t${store.tokens.length + 1}`, userId, tokenHash: hashToken(token), consumedAt: null, expiresAt: new Date(Date.now() + 15 * 60 * 1000) });
  return token;
}

export async function consumeMagicLink(prisma, { token }) {
  const tokenHash = hashToken(token);

  const magicToken = await prisma.magicLinkToken.findFirst({
    where: { tokenHash, consumedAt: null, now: new Date() },
  });

  if (!magicToken) {
    throw new HttpError(400, 'Magic link is invalid or expired');
  }

  return prisma.$transaction(async (tx) => {
    const consumeResult = await tx.magicLinkToken.updateMany({
      where: {
        id: magicToken.id,
        consumedAt: null,
      },
      data: {
        consumedAt: new Date(),
      },
    });

    if (consumeResult.count !== 1) {
      throw new HttpError(400, 'Magic link already consumed');
    }

    const session = { id: `s${tx.sessions.length + 1}`, userId: magicToken.userId };
    tx.sessions.push(session);
    return { sessionId: session.id };
  });
}

