// Adapted from tenantadmin server/src/services/authService.js:373-420 @ e9a4b45
// (Prisma replaced by injected stores; the NODE_ENV default from
// server/src/config/env.js:5 reproduced by parseEnv). This is the request side of the
// magic-link flow BEFORE the dev shortcut under review.
import { createHash, randomBytes } from 'node:crypto';

export function parseEnv(source) {
  return {
    NODE_ENV: source.NODE_ENV ?? 'development',
    APP_BASE_URL: source.APP_BASE_URL ?? 'http://localhost:5173',
    MAGIC_LINK_TTL_MINUTES: Number(source.MAGIC_LINK_TTL_MINUTES ?? 15),
  };
}

const hashToken = (token) => createHash('sha256').update(token).digest('hex');

export function createMagicLinkRequester({ env, users, tokens, log = () => {} }) {
  return async function requestMagicLink({ email }) {
    const normalizedEmail = email.trim().toLowerCase();
    const user = users.find((u) => u.email === normalizedEmail);

    if (!user) {
      return { accepted: true };
    }

    const token = randomBytes(48).toString('hex');
    const expiresAt = new Date(Date.now() + env.MAGIC_LINK_TTL_MINUTES * 60 * 1000);
    tokens.push({ userId: user.id, tokenHash: hashToken(token), expiresAt, consumedAt: null });

    const magicLinkUrl = `${env.APP_BASE_URL}/magic-link?token=${token}`;
    log(`Magic link for ${user.email}: ${magicLinkUrl}`);

    return {
      accepted: true,
    };
  };
}
